//! 🏛️ Pending Commit identities come from bounded loans of original typed Store edits.
use super::*;
use super::transition_ids::OriginalTransitionIds;
/// 🧮️ Two bounded passes count exact canonical headers and then read each original operation identity.
pub struct OriginalCommitMutationIds{binding:Option<OriginalSourceBinding>,store:usize,generation:u64,revision:[u8;32],pending:(usize,usize),key:Option<ArtifactHistoryKey>,index:usize,offset:usize,operation:usize,count:usize,pass:u8,matched:bool,ready:bool,closing:bool,ids:OriginalTransitionIds}
impl Default for OriginalCommitMutationIds{fn default()->Self{Self{binding:None,store:0,generation:0,revision:[0;32],pending:(0,0),key:None,index:0,offset:0,operation:0,count:0,pass:0,matched:false,ready:false,closing:false,ids:Default::default()}}}
impl OriginalCommitMutationIds{
 /// 🪪️ The fallback is a borrowed edit prefix plus an independently formatted fixed integer suffix.
 pub(super) fn identity<'a,P,M>(edit:&'a semio_framework_os_spr::Edit<M>,index:usize)->Result<(&'a str,Option<usize>),ValueError>where M:Mutation<P>{let operation=edit.forwards.get(index).ok_or_else(||invalid("Commit operation source disappeared"))?;Ok(match edit.mutation_meta.get(index).and_then(|meta|meta.mutation_id.as_ref()).or_else(||operation.mutation_id()){Some(id)=>(id.0.as_str(),None),None=>(edit.id.as_str(),Some(index))})}
 /// 🔍️ Each lookup compares at most 64 original key bytes before advancing one original ledger key.
 pub fn advance<P,M>(&mut self,store:&ArtifactStore<P,M>,pending:&[String],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{
  if self.closing{return Err(invalid("closing Commit identities cannot resume").into())}if let Some(binding)=self.binding{if !binding.matches(cx)||self.store!=store as*const _ as usize||self.generation!=store.generation()||self.revision!=store.content_revision()||self.pending!=(pending.as_ptr()as usize,pending.len()){return Err(invalid("Commit identities changed their original caller, Store or pending vector").into())}}if self.ready{return Ok(true)}let log=store.parts_ref().log;
  if self.binding.is_none(){let binding=OriginalSourceBinding::borrow(cx);action(cx,fixed(256),|_|{self.binding=Some(binding);self.store=store as*const _ as usize;self.generation=store.generation();self.revision=store.content_revision();self.pending=(pending.as_ptr()as usize,pending.len());self.key=log.envelope.vcs.edits.last_key();Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;return Ok(false)}
  if self.index==pending.len(){if self.pass==0{action(cx,fixed(256),|_|{self.pass=1;self.index=0;self.key=log.envelope.vcs.edits.last_key();self.matched=false;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;}else if self.count==0&&self.ids.values().is_empty(){let d=self.ids.demands("",None,0)?;action(cx,d,|grant|self.ids.advance("",None,0,grant))?;if self.ids.ready(){action(cx,fixed(128),|_|{self.ready=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()})})?;}}else{action(cx,fixed(128),|_|{self.ready=true;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()})})?;}return Ok(self.ready)}
  let key=self.key.ok_or_else(||invalid("Commit pending edit has no original Store row"))?;let edit=log.envelope.vcs.edits.get_key(key).ok_or_else(||invalid("Commit original Store row disappeared"))?;
  if !self.matched{action(cx,fixed(256),|_|{let original=&pending[self.index];let end=(self.offset+64).min(original.len());if edit.id.len()!=original.len()||edit.id.as_bytes()[self.offset..end]!=original.as_bytes()[self.offset..end]{self.key=log.envelope.vcs.edits.previous_key(key);self.offset=0;}else if end==original.len(){self.matched=true;self.offset=0;}else{self.offset=end;}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;return Ok(false)}
  if self.pass==0||self.operation==edit.forwards.len(){action(cx,fixed(256),|_|{if self.pass==0{self.count=self.count.checked_add(edit.forwards.len()).ok_or_else(||invalid("Commit operation header extent overflow"))?;}self.index+=1;self.operation=0;self.offset=0;self.key=log.envelope.vcs.edits.last_key();self.matched=false;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;return Ok(false)}
  let(source,suffix)=Self::identity::<P,M>(edit,self.operation)?;let complete=self.ids.complete();let mut d=self.ids.demands(source,suffix,self.count)?;d.copy_bytes=d.copy_bytes.checked_add(128).ok_or_else(||invalid("Commit identity coordination extent overflow"))?;action(cx,d,|grant|{let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-128,..grant};let p=self.ids.advance(source,suffix,self.count,child)?;if self.ids.complete()!=complete{self.operation+=1;}p.checked_add(RetainedCloneProgress{copied_bytes:128,..Default::default()})})?;Ok(false)
 }
 pub fn ready(&self)->bool{self.ready&&!self.closing}
 pub fn values(&self)->&[semio_framework_os_spr::MutationId]{self.ids.values()}
 /// 🤝️ Moves the exact canonical identity vector after all original typed edit loans have returned.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<Vec<semio_framework_os_spr::MutationId>>)->Result<bool,OriginalTurnFailure>{if !self.ready()||!self.binding.is_some_and(|binding|binding.matches(cx)){return Err(invalid("Commit identities handoff changed its original caller").into())}let grant=cx.retained_grant();admit_original_construction(cx,output,construction(fixed(256)),|_|{let(values,p)=self.ids.take(grant)?.ok_or_else(||invalid("Commit identity grant disappeared"))?;Ok((values,p))})}
 /// 📏️ The original vector's typed close or the final Store coordinate return determines demand.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.ids.terminal_is_empty(){return self.ids.close_demands(body)}Ok(if self.binding.is_some(){fixed(128)}else{Default::default()})}
 /// ♻️ Partial canonical identities physically close before original Store coordinates are forgotten.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if let Some(binding)=self.binding{if !binding.matches(cx){return Err(invalid("Commit identity close changed its original caller").into())}}self.closing=true;if !self.ids.terminal_is_empty(){let d=self.ids.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|self.ids.close_step(grant))?;return Ok(false)}if self.binding.is_some(){close_original_retained_step(cx,fixed(128),|_|{self.binding=None;self.key=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()}))})?;}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.ids.terminal_is_empty()}
}
